import React, { useState, useEffect } from "react";
import api from "../../api"; // Pastikan file API Anda sudah terkonfigurasi dengan Axios
import { FaPlus } from "react-icons/fa";

const Syarat = () => {
  const [data, setData] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    api.get("/syarat") // Endpoint untuk tabel syarat
      .then((response) => {
        setData(response.data);
      })
      .catch((error) => {
        console.error("Error fetching data:", error);
      })
      .finally(() => {
        setLoading(false);
      });
  }, []);

  return (
    <div>
      <div className="bg-white w-full max-w-4xl mx-auto rounded-lg shadow-lg p-6">
        <div className="flex justify-between mb-4">
          <h1 className="text-2xl font-bold mb-4">Data Syarat</h1>
          <button
            // onClick={handleOpenCreateModal}
            className="bg-teal-500 text-white py-2 px-4 rounded-lg flex items-center"
          >
            <FaPlus className="inline-block mr-2 mb-1" /> Create Artikel
          </button>
        </div>
        <table className="min-w-full bg-white border border-gray-300 rounded-lg shadow">
          <thead className="bg-teal-700 text-white">
            <tr>
              <th className="px-6 py-3 text-left font-medium">No</th>
              <th className="px-6 py-3 text-left font-medium">Syarat</th>
            </tr>
          </thead>
          <tbody>
            {loading ? (
              <tr>
                <td colSpan="2" className="text-center px-6 py-4 text-gray-500">
                  Loading...
                </td>
              </tr>
            ) : data.length > 0 ? (
              data.map((row, index) => (
                <tr key={row.id}>
                  <td className="px-6 py-4">{index + 1}</td>
                  <td className="px-6 py-4">{row.syarat}</td>
                </tr>
              ))
            ) : (
              <tr>
                <td colSpan="2" className="text-center px-6 py-4 text-gray-500">
                  No data available.
                </td>
              </tr>
            )}
          </tbody>
        </table>
      </div>
    </div>
  );
};

export default Syarat;
